files.content:
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-color: #fff;
  background-image: url(https://code.s3.yandex.net/web-code/images/dotted.svg);
}

.cover {
  position: relative;
  display: grid;
  place-items: center;
  padding: 5%;
  text-transform: uppercase;
  background-position: center;
  background-size: cover;
  aspect-ratio: 16 / 9;
}

.cover-image {
  position: absolute;
  inset: 0;
  z-index: -1;
  inline-size: 100%;
  block-size: 100%;
  object-fit: cover;
  filter: brightness(70%);
}

.heading {
  color: #fff;
  font-family: sans-serif;
  font-size: 4em;
  hyphens: auto;
  text-wrap: balance;
}

.content {
  inline-size: 90%;
  margin: 40px auto;
  border: 1px solid #000;
  padding: 2em;
  background-color: #fff;
}

.content__title {
  margin: 0;
  font-size: 45px;
  text-transform: uppercase;
  hyphens: auto;
}
